(()=>{const t=document.querySelector('[data-menu]'),n=document.querySelector('[data-nav]');if(t&&n){const c=()=>{n.classList.remove('open');t.setAttribute('aria-expanded','false')};t.addEventListener('click',()=>{const o=n.classList.toggle('open');t.setAttribute('aria-expanded',String(o))});n.querySelectorAll('a').forEach(a=>a.addEventListener('click',c));document.addEventListener('keydown',e=>{if(e.key==='Escape')c()})}document.querySelectorAll('[data-ba]').forEach(e=>{const r=e.querySelector('input');if(r){const u=()=>e.style.setProperty('--p',r.value+'%');r.addEventListener('input',u,{passive:true});u()}});document.querySelectorAll('[data-wa-form]').forEach(f=>f.addEventListener('submit',e=>{e.preventDefault();if(!f.reportValidity())return;const d=new FormData(f),ar=f.dataset.lang==='ar',v=k=>String(d.get(k)||'').trim(),lines=ar?['مرحباً، أود طلب معاينة أو عرض سعر من قصر الشمالي.',`الاسم: ${v('name')}`,`الهاتف: ${v('phone')}`,v('city')?`المدينة: ${v('city')}`:'',v('service')?`الخدمة: ${v('service')}`:'',v('message')?`تفاصيل المشروع: ${v('message')}`:'']:['Hello, I would like a site visit or quotation from Al Qaser Al Shamali.',`Name: ${v('name')}`,`Phone: ${v('phone')}`,v('city')?`City: ${v('city')}`:'',v('service')?`Service: ${v('service')}`:'',v('message')?`Project details: ${v('message')}`:''];window.open('https://wa.me/971507427070?text='+encodeURIComponent(lines.filter(Boolean).join('\n')),'_blank','noopener,noreferrer')}));document.querySelectorAll('[data-year]').forEach(e=>e.textContent=new Date().getFullYear())})();
